__NUXT_JSONP__("/tr/about", (function(a){return {data:[{details:{slug:"tr",pageTitle:"MLI nedir? | Mentor Language Institute",pageDescription:"Mentor Language Institute 2002 yılında kuruldu ve iki popüler alandayız : Westwood ve Hollywood.",section1:{title:"MLI nedir?",description:["Mentor Language Institute 2002 yılında kuruldu ve iki popüler alandayız : Westwood ve Hollywood. \u003Cbr \u002F\u003EDünyanın her yerinden gelen öğrencilerin İngilizcelerini geliştirmelerine yardımcı oluyoruz"]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Kaliteli Sınıflar için Daha Az Ödeyin",description:["İki şeye değer veriyoruz:  \u003Cb\u003E“Eğitimin Kalitesi”\u003C\u002Fb\u003E ve \u003Cb\u003E“Fiyat.”\u003Cb\u003E","İngilizce, dünyanın dört bir yanından insanlarla iletişim için küresel bir dil ve gerekli bir araçtır. Umudumuz, uluslararası öğrencilerin dünyada başarılı olmak için İngilizce becerilerini kazanmalarıdır.\u003Cbr \u002F\u003EBu nedenle, sınıfların kalitesine ve düşük fiyata odaklanıyoruz."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"2020 itibariyle 17.000'den fazla öğrenci MLI'ı seçti ve mezun oldu.",description:["ESL programını (6 beceri alanına sahip Genel İngilizce Programı: Dilbilgisi \u002F Yazma, Okuma \u002F Kelime Bilgisi ve Dinleme \u002F Konuşma), TOEFL®, IELTS ™ (üniversiteye gitmek için hazırlanmak isteyen öğrenciler için) sunuyoruz., ve TOEIC®.","Birçok öğrenci, UCLA, USC ve Santa Monica College gibi ABD'deki üniversitelerde eğitim görmeye devam etti."],lists:[{link:"\u002Ftr\u002Ffeature",image:a,text:"Insanlarin MLI'ı Seçmeleri'nin 5 Nedeni"},{link:"\u002Ftr\u002Fcompany",image:a,text:"Şirket Bilgisi"},{link:"\u002Ftr\u002Fimage-gallery",image:a,text:"Fotoğraf \u002F video galerisi"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:28.463Z",updatedAt:"2025-05-26T12:06:27.575Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));